using System.Text;

namespace Ducky.Shared.Generators;

/// <summary>
/// Writes a generated file from C# raw string literal templates (SPEC §16.1, R-PKG-4): each template line is re-indented
/// at the current block depth, and the file opens with the GEN-06 prologue. Lines end with <c>\n</c> whatever the
/// template's line endings.
/// </summary>
internal sealed class CodeWriter
{
    private readonly StringBuilder _builder = new("""
        // <auto-generated/>
        #nullable enable


        """);

    private int _depth;

    /// <summary>Appends each line of <paramref name="text"/> at the current depth; empty lines stay empty.</summary>
    public CodeWriter Line(string text = "")
    {
        foreach (var line in text.Split('\n'))
        {
            var content = line.TrimEnd('\r');
            if (content.Length > 0)
            {
                _builder.Append(' ', 4 * _depth).Append(content);
            }

            _builder.Append('\n');
        }

        return this;
    }

    /// <summary>Writes <paramref name="header"/> and an opening brace, then indents.</summary>
    public CodeWriter Open(string header)
    {
        Line(header).Line("{");
        _depth++;
        return this;
    }

    /// <summary>Outdents and writes the closing brace.</summary>
    public CodeWriter Close()
    {
        _depth--;
        return Line("}");
    }

    public override string ToString() => _builder.ToString();
}
